mapper.select:
select sum(amount) as amountTotal
from sky_take_out.orders
where status = 5 and order_time between #{begin} and #{end};

select
    count(case when order_time between #{begin}
        and #{end} then 1 end) as orderCount
    from sky_take_out.orders
union all
select
    count(case when status = 5 and order_time between #{begin}
        and #{end} then 1 end) as validOrderCount
    from sky_take_out.orders;
